message.content:
{
  "definition_simple": "法律や道徳に反することや、罪・間違いをする。",
  "definition_standard": "法律・規則・道徳などに背く行為をする。また、罪や取り返しのつかない過ちを行う。",
  "pos": "動詞（サ行五段活用、他動詞）",
  "semantic_class": "action",
  "sentences": [
    {
      "tier": "T1",
      "sentence": "彼は罪を犯した。"
    },
    {
      "tier": "T2",
      "sentence": "どんな理由があっても、法を犯してはならない。"
    },
    {
      "tier": "T3",
      "sentence": "彼は若い頃に重大な過ちを犯してしまった。"
    },
    {
      "tier": "T3",
      "sentence": "大会の規則を犯した選手は、出場資格を失った。"
    },
    {
      "tier": "T4",
      "sentence": "その男は再び同じ罪を犯すことを恐れていた。"
    },
    {
      "tier": "T4",
      "sentence": "彼は社の服務規程を犯し、厳しい懲戒処分を受けた。"
    },
    {
      "tier": "T5",
      "sentence": "私たちは人類が過去に犯してきた過ちから教訓を学ばねばならない。"
    },
    {
      "tier": "T5",
      "sentence": "地域の神聖なタブーを犯した観光客が厳しく非難された。"
    },
    {
      "tier": "T6",
      "sentence": "国際法上の人道に対する罪を犯した疑いで、元高官が国際刑事裁判所に起訴された。"
    },
    {
      "tier": "T6",
      "sentence": "共同体の禁忌を犯すことへの宗教的畏怖が、秩序の崩壊を未然に防いできた。"
    }
  ],
  "morphological_forms": [
    {
      "label": "past_tense",
      "form": "犯した"
    },
    {
      "label": "negative",
      "form": "犯さない"
    },
    {
      "label": "passive",
      "form": "犯される"
    }
  ],
  "morphology_wrong_forms": [
    {
      "base_form": "犯した",
      "wrong_forms": [
        {
          "form": "犯いだ",
          "explanation": "カ行五段動詞（書く→書いた）の音便規則をサ行五段動詞に誤って適用している。"
        },
        {
          "form": "犯った",
          "explanation": "ラ行五段動詞の促音便（割る→割った）の活用規則と混同している。"
        },
        {
          "form": "犯したた",
          "explanation": "過去形語尾「た」を重複して付加してしまっている。"
        }
      ]
    },
    {
      "base_form": "犯さない",
      "wrong_forms": [
        {
          "form": "犯しない",
          "explanation": "一段動詞の未然形接続規則（連用形＋ない）をサ行五段動詞に誤適用している。"
        },
        {
          "form": "犯くない",
          "explanation": "動詞の否定形活用をイ形容詞の否定形規則（〜くない）と混同している。"
        },
        {
          "form": "犯ぜない",
          "explanation": "未然形語尾の子音を誤って濁音化させ、可能否定のような不自然な語形を作っている。"
        }
      ]
    },
    {
      "base_form": "犯される",
      "wrong_forms": [
        {
          "form": "犯せられる",
          "explanation": "仮定形／可能動詞語幹に「られる」を付加した二重受身・可能混同の誤り。"
        },
        {
          "form": "犯しられる",
          "explanation": "一段動詞の受身化規則（連用形＋られる）をサ行五段動詞に誤適用している。"
        },
        {
          "form": "犯さられる",
          "explanation": "五段動詞の受身未然形「あ段＋れる」に不要な「ら」を挿入した過剰受身形。"
        }
      ]
    }
  ],
  "primary_collocate": "罪を犯す",
  "collocation_distractors": [
    {
      "word": "刑罰",
      "explanation": "「刑罰」は受ける・科す対象であり、法を破る側が「行う」名詞ではないためコロケーションとして不成立。"
    },
    {
      "word": "事故",
      "explanation": "「事故」は過失や偶然による出来事であり「起こす」「遭う」と結びつき、道徳・法規を破る意味の「犯す」とは結びつかない。"
    },
    {
      "word": "嘘",
      "explanation": "虚偽の発言には専用の動詞「つく（嘘をつく）」を用い、「犯す」とは共起しない。"
    }
  ],
  "collocation_wrong_collocate": {
    "word": "失敗",
    "explanation": "英語の make a mistake に引きずられて「失敗を犯す」としがちだが、日本語では「失敗をする」または「過ちを犯す」とするのが正しく、「失敗」と「犯す」はコロケーションとして不自然。"
  },
  "cloze_distractors": [
    {
      "word": "破棄して",
      "explanation": "「破棄する」は書類や契約を一方的に捨てる・無効にする動作を表し、「法」を規範として破る文脈では意味が合わない。"
    },
    {
      "word": "侵略して",
      "explanation": "同音の「侵す」に関連する軍事・領土侵害の語であり、一般的な「法」という規範を破る述語としては不適切。"
    },
    {
      "word": "傷つけて",
      "explanation": "人や感情、物理的な物体を痛める動詞であり、「法」のような抽象的規則を対象とする目的語選択として比喩的にも不自然。"
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "彼の心の中に罪が犯した。",
      "explanation": "「犯す」は意志または行為主体を主語とする他動詞（〜が〜を犯す）であり、「罪」を主語にして自動詞のように用いる項構造の誤り。"
    },
    {
      "sentence": "危険を犯してまで、大雨の中で山に登るべきではない。",
      "explanation": "危険や困難に身を投じる意味には同音異義語の「冒す（危険を冒す）」を用いるべきであり、罪・規則違反を表す「犯す」の漢字表記は不適切。"
    },
    {
      "sentence": "軍隊が隣国の国境を犯して侵入した。",
      "explanation": "領域や権利、身体を侵害する意味には「侵す（領土を侵す・権利を侵す）」を用いるべきであり、犯罪行為を行う意味の「犯す」は不適切。"
    }
  ],
  "spot_incorrect": {
    "sentence": "いくら時間に追われていたとしても、スピード違反という失敗を犯してはならない。",
    "error_description": "「犯す」は「罪」や「過ち」と共起する語であり、「失敗」と結びつけるのは不自然なコロケーションである。",
    "corrected": "いくら時間に追われていたとしても、スピード違反という過ちを犯してはならない。"
  },
  "word_family_forms": [
    "犯人",
    "再犯",
    "共犯"
  ],
  "word_family_fake_forms": [
    "犯手",
    "犯癖",
    "犯死"
  ],
  "syn_ant_candidates": [
    {
      "word": "破る",
      "relation": "synonym"
    },
    {
      "word": "踏みにじる",
      "relation": "synonym"
    },
    {
      "word": "守る",
      "relation": "antonym"
    },
    {
      "word": "順守する",
      "relation": "antonym"
    }
  ],
  "particle_candidates": [
    {
      "particle": "を",
      "is_correct": true,
      "explanation": "他動詞「犯す」の直接目的語（行われた過ち・罪）を示す格助詞として正しい。"
    },
    {
      "particle": "に",
      "is_correct": false,
      "explanation": "「に」は帰着点や対象を示す助詞であり、行為の直接の内容である「過ち」を受ける助詞として誤り。"
    },
    {
      "particle": "が",
      "is_correct": false,
      "explanation": "「が」は主語（行為主体）を指し示すため、動作の対象である「過ち」に付けると主客が逆転してしまう。"
    },
    {
      "particle": "で",
      "is_correct": false,
      "explanation": "「で」は手段や場所を表す格助詞であり、「犯す」が要求する被影響目的語を標示できない。"
    }
  ]
}
